        field(fd,"cgroup.events","frozen",&frozen)||frozen!=1||field(fd,"cgroup.stat","nr_descendants",&descendants)||descendants||
        (empty&&(field(fd,"cgroup.events","populated",&populated)||populated))?-1:0;
